        assertEq(initialBalance, 0, "Initial balance should be zero");

        // Perform the attack - this will fail due to modifier checks
        vm.expectRevert();
        attacker.startAttack();

        // Verify the attack was prevented by the hasNoBalance modifier
        uint finalBalance = modifierEntrancy.getTokenBalance(address(attacker));
        assertEq(finalBalance, 0, "Attacker should not receive any tokens");
    }

    function testDirectCallSupportsToken() public {
        // Directly call supportsToken to demonstrate the reentrancy potential
